class Solution { int longest(string& value,int k,char changedValue){int left=0,changed=0,answer=0;for(int right=0;right<(int)value.size();++right){changed+=value[right]==changedValue;while(changed>k)changed-=value[left++]==changedValue;answer=max(answer,right-left+1);}return answer;}public: int maxConsecutiveAnswers(string answerKey,int k){return max(longest(answerKey,k,'T'),longest(answerKey,k,'F'));} };
